def backfill_financials_and_assignees(apps, schema_editor):
    Appointment = apps.get_model("operations", "Appointment")
    AppointmentAssignee = apps.get_model("operations", "AppointmentAssignee")
    for appointment in Appointment.objects.all().iterator():
        appointment.subtotal = appointment.total
        appointment.amount_paid = appointment.total if appointment.payment_status == "paid" else 0
        appointment.save(update_fields=("subtotal", "amount_paid"))
        if appointment.employee_id:
            AppointmentAssignee.objects.get_or_create(
                tenant_id=appointment.tenant_id, appointment_id=appointment.id,
                employee_id=appointment.employee_id,
                defaults={"salary_share_percent": 100, "is_primary": True},
            )


